{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "A close tryptamine analogue sharing the 2-methylindole-ethylamine motif has an in vivo mouse brain-to-plasma ratio of 0.16 and is reported as BBB-permeable, supporting meaningful CNS access for the shared scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A structurally similar tryptamine analogue shows a mouse brain-to-plasma ratio of 0.5 and is reported as BBB-permeable, supporting CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A related tryptamine analogue has a mouse brain-to-plasma ratio of 0.4 and is described as having good brain penetration, supporting CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Belinostat, which shares the cinnamohydroxamic acid warhead, was detected in brain with activity after systemic administration, indicating that this warhead does not absolutely prevent BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Belinostat showed limited CSF penetration (<10% of free plasma exposure) in non-human primates, a contradictory signal that the hydroxamic acid warhead may restrict free CNS exposure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: multiple in vivo brain-penetration measurements in close tryptamine analogues and evidence that the cinnamohydroxamic acid warhead can reach brain support meaningful CNS access, despite physicochemical ionization concerns and mixed CSF data for belinostat.",
  "evidence_gaps": [
    "No direct brain or CSF pharmacokinetic measurement for M344 itself.",
    "Belinostat CSF data are mixed and come from a less similar molecule; unbound brain concentrations for the query are unknown.",
    "Transporter-mediated efflux or uptake contributions are not directly measured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

